	REQUIRE(lane->bridge()->addDevice(feathers::fx::busutil::kTraits.tag) != kNoInstance);
	CHECK(card.updateContent());
	CHECK(card.laneChipTextForTest() == std::string(ui::DelayCard::kLaneChipPrefix) + "2");
